#!/usr/bin/env bash
# Reproducible local AST graph; no LLM backend or API charges.
set -euo pipefail
cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.."
export GRAPHIFY_BACKEND=none
# Keep Graphify independent of the gateway venv and macOS's older system Python.
graphify_runner=(uv tool run --python 3.12 --from 'graphifyy[sql]==0.9.107' graphify)
if [[ $# -eq 0 ]]; then
    "${graphify_runner[@]}" extract . --code-only --max-workers 2
    "${graphify_runner[@]}" export html
else
    "${graphify_runner[@]}" "$@"
fi
# Reports are generated by the CLI but not needed for scoped queries.
rm -f graphify-out/GRAPH_REPORT.md
